window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-313c16cf42e4a16b"]={"versions": [{"id": "FIG-313c16cf42e4a16b", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Prozess-Phasenmodell / linearer Workflow (Chevron-Ablaufdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Quality &amp; Conformance Framework (Dokument: <code>AUTOSAR_DS_Accreditation</code>, Releases R2.1.20 / R3.0.7).\n</li><li><strong>Technischer Zweck:</strong> Definition des standardisierten, vierstufigen Akkreditierungs- und Konformitätsprüfungs-Workflows für AUTOSAR-Basissoftware (BSW), Werkzeuge (Authoring/Generation Tools) oder Entwicklungsorganisationen zur formalen Validierung gegen Spezifikationsanforderungen (SRS/SWS).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Entitäten (Phasen-Blöcke):</strong>\n<ul class=\"fig-list\"><li><code>Information/ criteria exchange</code>: Bidirektionale Abstimmungsphase zwischen Evaluierungsstelle (Accreditation Body) und BSW-/Werkzeug-Hersteller.\n</li><li><code>Self Assessment</code>: Interne Verifikationsphase durch den Modulhersteller/Tier-1.\n</li><li><code>Independent Assessment</code>: Externe, neutrale Audit- und Testphase durch eine autorisierte Akkreditierungsstelle.\n</li><li><code>Accreditation</code>: Formaler Abschluss mit Zertifikatserteilung bzw. Konformitätsbestätigung.\n</li></ul>\n</li><li><strong>Akteure &amp; Artefakte (implizit nach DS_Accreditation):</strong>\n<ul class=\"fig-list\"><li><em>Applicant / Vendor:</em> Stellt BSW-Implementierung, Konformitätstestberichte und Konfigurationsdateien (<code>.arxml</code>) bereit.\n</li><li><em>Accreditation Body / Independent Assessor:</em> Liefert Kriterienkatalog, prüft Testvektoren und erteilt Akkreditierung.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Sequenzielle, strikt gerichtete 1:1-Vorgänger-Nachfolger-Beziehung (Phase_n → Phase_n+1).\n</li><li>Keine Verzweigungen oder parallelen Ausführungspfade auf dieser Makroebene.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1: <code>Information/ criteria exchange</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Antrag auf Konformitätsprüfung für spezifische BSW-Module oder Toolchains.\n</li><li><em>Aktion:</em> Bereitstellung des normativen Kriterienkatalogs, Festlegung des Ziel-Releases (z. B. R3.0) und Abgrenzung des Testumfangs (SWS-Abdeckung, zulässige Modul-Subsets).\n</li></ul>\n</li><li><strong>Schritt 2: <code>Self Assessment</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Vollständige Test- und Kriteriendefinition.\n</li><li><em>Aktion:</em> Ausführung standardisierter Testsuiten (Conformance Tests / ATS) auf lokaler Hardware/Simulationsumgebung; Erstellung des internen Konformitätsberichts; Behebung identifizierter Nicht-Konformitäten.\n</li></ul>\n</li><li><strong>Schritt 3: <code>Independent Assessment</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Übergabe des Selbstevaluierungsberichts und der Testartefakte an den Assessor.\n</li><li><em>Aktion:</em> Wiederholung und Auditierung relevanter Testfälle (Black-Box-Tests, API-Signaturprüfungen, Verhalten bei Fehlern via Det/Dem); Verifikation der ARXML-Metamodellkonformität.\n</li></ul>\n</li><li><strong>Schritt 4: <code>Accreditation</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Positiver Prüfbericht ohne kritische Abweichungen (Non-Conformances).\n</li><li><em>Aktion:</em> Formale Ausstellung des Konformitätszertifikats für das definierte Modul-Release.\n</li></ul>\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Abbruch-/Rückschleifen-Bedingungen:</strong> Schlägt Schritt 2 oder Schritt 3 fehl (Nicht-Erfüllung zwingender SWS-Anforderungen), ist eine Iteration innerhalb der jeweiligen Phase bzw. ein Re-Audit erforderlich, bevor Phase 4 erreicht werden kann.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW- &amp; Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Modul-APIs müssen exakt den C-Signaturen der jeweiligen SWS entsprechen (einschließlich Reentrancy, Parametertypen, Return-Values und Det-Fehlercodes).\n</li><li>Selbst-Tests müssen lückenlose Nachweise (Traceability) über alle verpflichtenden Anforderungen (<code>[SWS_...]</code>) liefern.\n</li></ul>\n</li><li><strong>Toolchain &amp; Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Generierte BSW-Konfigurationen (<code>.h</code>/<code>.c</code>) sowie das zugrundeliegende BSW-Modul-Design müssen die Schemakonformität des AUTOSAR-Metamodells strikt einhalten.\n</li></ul>\n</li><li><strong>Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm definiert einen Governance-/Qualitätsprozess und keinen On-Chip-Laufzeit-Mechanismus (keine Laufzeit-APIs, keine OS-Tasks, keine RTE-Beteiligung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d3ff0d714543db16", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Prozess-Phasenmodell / linearer Workflow (Chevron-Ablaufdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Quality &amp; Conformance Framework (Dokument: <code>AUTOSAR_DS_Accreditation</code>, Releases R2.1.20 / R3.0.7).\n</li><li><strong>Technischer Zweck:</strong> Definition des standardisierten, vierstufigen Akkreditierungs- und Konformitätsprüfungs-Workflows für AUTOSAR-Basissoftware (BSW), Werkzeuge (Authoring/Generation Tools) oder Entwicklungsorganisationen zur formalen Validierung gegen Spezifikationsanforderungen (SRS/SWS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Entitäten (Phasen-Blöcke):</strong>\n<ul class=\"fig-list\"><li><code>Information/ criteria exchange</code>: Bidirektionale Abstimmungsphase zwischen Evaluierungsstelle (Accreditation Body) und BSW-/Werkzeug-Hersteller.\n</li><li><code>Self Assessment</code>: Interne Verifikationsphase durch den Modulhersteller/Tier-1.\n</li><li><code>Independent Assessment</code>: Externe, neutrale Audit- und Testphase durch eine autorisierte Akkreditierungsstelle.\n</li><li><code>Accreditation</code>: Formaler Abschluss mit Zertifikatserteilung bzw. Konformitätsbestätigung.\n</li></ul>\n</li><li><strong>Akteure &amp; Artefakte (implizit nach DS_Accreditation):</strong>\n<ul class=\"fig-list\"><li><em>Applicant / Vendor:</em> Stellt BSW-Implementierung, Konformitätstestberichte und Konfigurationsdateien (<code>.arxml</code>) bereit.\n</li><li><em>Accreditation Body / Independent Assessor:</em> Liefert Kriterienkatalog, prüft Testvektoren und erteilt Akkreditierung.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Sequenzielle, strikt gerichtete 1:1-Vorgänger-Nachfolger-Beziehung (Phase_n → Phase_n+1).\n</li><li>Keine Verzweigungen oder parallelen Ausführungspfade auf dieser Makroebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1: <code>Information/ criteria exchange</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Antrag auf Konformitätsprüfung für spezifische BSW-Module oder Toolchains.\n</li><li><em>Aktion:</em> Bereitstellung des normativen Kriterienkatalogs, Festlegung des Ziel-Releases (z. B. R3.0) und Abgrenzung des Testumfangs (SWS-Abdeckung, zulässige Modul-Subsets).\n</li></ul>\n</li><li><strong>Schritt 2: <code>Self Assessment</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Vollständige Test- und Kriteriendefinition.\n</li><li><em>Aktion:</em> Ausführung standardisierter Testsuiten (Conformance Tests / ATS) auf lokaler Hardware/Simulationsumgebung; Erstellung des internen Konformitätsberichts; Behebung identifizierter Nicht-Konformitäten.\n</li></ul>\n</li><li><strong>Schritt 3: <code>Independent Assessment</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Übergabe des Selbstevaluierungsberichts und der Testartefakte an den Assessor.\n</li><li><em>Aktion:</em> Wiederholung und Auditierung relevanter Testfälle (Black-Box-Tests, API-Signaturprüfungen, Verhalten bei Fehlern via Det/Dem); Verifikation der ARXML-Metamodellkonformität.\n</li></ul>\n</li><li><strong>Schritt 4: <code>Accreditation</code></strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Positiver Prüfbericht ohne kritische Abweichungen (Non-Conformances).\n</li><li><em>Aktion:</em> Formale Ausstellung des Konformitätszertifikats für das definierte Modul-Release.\n</li></ul>\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Abbruch-/Rückschleifen-Bedingungen:</strong> Schlägt Schritt 2 oder Schritt 3 fehl (Nicht-Erfüllung zwingender SWS-Anforderungen), ist eine Iteration innerhalb der jeweiligen Phase bzw. ein Re-Audit erforderlich, bevor Phase 4 erreicht werden kann.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW- &amp; Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Modul-APIs müssen exakt den C-Signaturen der jeweiligen SWS entsprechen (einschließlich Reentrancy, Parametertypen, Return-Values und Det-Fehlercodes).\n</li><li>Selbst-Tests müssen lückenlose Nachweise (Traceability) über alle verpflichtenden Anforderungen (<code>[SWS_...]</code>) liefern.\n</li></ul>\n</li><li><strong>Toolchain &amp; Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Generierte BSW-Konfigurationen (<code>.h</code>/<code>.c</code>) sowie das zugrundeliegende BSW-Modul-Design müssen die Schemakonformität des AUTOSAR-Metamodells strikt einhalten.\n</li></ul>\n</li><li><strong>Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm definiert einen Governance-/Qualitätsprozess und keinen On-Chip-Laufzeit-Mechanismus (keine Laufzeit-APIs, keine OS-Tasks, keine RTE-Beteiligung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-313c16cf42e4a16b", "to": "FIG-d3ff0d714543db16", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
